CREATE OR ALTER TRIGGER trg_module_delete_denorm
ON module
AFTER DELETE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @AffectedCourses TABLE (course_id BIGINT);

INSERT INTO @AffectedCourses (course_id)
SELECT DISTINCT course_id
FROM deleted;

UPDATE c
SET c.total_lessons = (
    SELECT COUNT(l.id)
    FROM lesson l
    WHERE l.course_id = c.id
)
    FROM course c
    INNER JOIN @AffectedCourses ac ON c.id = ac.course_id;
END;
